<div class="grid3"><div class="card kpi"><div class="kpi-label">Balance Neto Total</div><div class="kpi-value blue">$<?= number_format($balanceTotal??0,2,',','.') ?></div><div class="sub">COP</div></div><div class="card kpi"><div class="kpi-label">Ingresos Totales</div><div class="kpi-value green">+$<?= number_format($ingresosTotales??0,2,',','.') ?></div><div class="sub">COP</div></div><div class="card kpi"><div class="kpi-label">Gastos Totales</div><div class="kpi-value pink">-$<?= number_format($gastosTotales??0,2,',','.') ?></div><div class="sub">COP</div></div></div>
