<section class="section dashboard-grid"><div class="card panel"><h3 id="formTitulo" class="section-title">Registrar movimiento <span class="scribble">↗</span></h3><form id="formTransaccion" action="index.php?url=dashboard" method="POST"><input type="hidden" name="action" id="formAction" value="guardar"><input type="hidden" name="id" id="formId" value=""><div class="field"><label>Tipo</label><select name="tipo" id="inputTipo"><option value="Gasto">Gasto</option><option value="Ingreso">Ingreso</option></select></div><div class="field"><label>Monto (COP)</label><input type="number" step="any" name="monto" id="inputMonto" placeholder="Ej: 50.000" required></div><div class="field"><label>Categoría</label><select name="categoria" id="inputCategoria" required><optgroup label="Gastos"><option>Alimentación</option><option>Vivienda</option><option>Servicios</option><option>Transporte</option><option>Salud</option><option>Educación</option><option>Entretenimiento</option><option>Ropa</option><option>Mascotas</option><option>Suscripciones</option><option>Deudas</option></optgroup><optgroup label="Ingresos"><option>Nómina / Salario</option><option>Ventas</option><option>Freelance</option><option>Inversiones</option><option>Premios / Regalos</option></optgroup><option>Otros</option></select></div><div class="field"><label>Método</label><select name="metodo_pago" id="inputMetodo"><option>Efectivo</option><option>Nequi</option><option>Daviplata</option><option>Transferencia Bancaria</option><option>Tarjeta de Crédito</option><option>Tarjeta de Débito</option></select></div><div class="field"><label>Fecha</label><input type="date" name="fecha" id="inputFecha" value="<?= date('Y-m-d') ?>" required></div><div class="field"><label>Descripción</label><input type="text" name="descripcion" id="inputDescripcion" placeholder="Detalle..."></div><button class="btn btn-blue full" type="submit" id="btnSubmit">Guardar movimiento ✈</button><button class="btn btn-soft full" type="button" id="btnCancelar" onclick="cancelarEdicion()" style="display:none;margin-top:8px">Cancelar edición</button></form></div><div class="card panel"><h3 class="section-title">Fuentes de ingresos <span class="scribble">↗</span></h3><div class="chart-box tall-chart"><canvas id="graficoIngresos"></canvas></div></div><div class="card panel"><h3 class="section-title">Distribución de gastos <span class="scribble pink-scribble">↗</span></h3><div class="chart-box tall-chart"><canvas id="graficoGastos"></canvas></div></div></section>
<section class="section card panel movement-panel"><div class="section-title-row"><h3 class="section-title">📜 Últimos movimientos <span class="scribble">↗</span></h3><span class="count-pill"><?= count($transacciones??[]) ?> registros</span></div><div class="responsive-table"><table class="list-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Categoría</th><th>Método</th><th>Monto</th><th>Descripción</th><th>Acciones</th></tr></thead><tbody><?php if(!empty($transacciones)): foreach($transacciones as $t): ?><tr><td><?= date('d/m/Y',strtotime($t['fecha'])) ?></td><td><span class="type-badge <?= strtolower($t['tipo'])==='ingreso'?'type-income':'type-expense' ?>"><?= htmlspecialchars($t['tipo']) ?></span></td><td><?= htmlspecialchars($t['categoria']) ?></td><td><?= htmlspecialchars($t['metodo_pago']) ?></td><td class="<?= strtolower($t['tipo'])==='ingreso'?'green':'pink' ?>" style="font-weight:800"><?= strtolower($t['tipo'])==='ingreso'?'+':'-' ?>$<?= number_format($t['monto'],0,',','.') ?></td><td><?= htmlspecialchars($t['descripcion'] ?? '-') ?></td><td><div class="row-actions"><button class="action-edit action-button" type="button" onclick='cargarParaEditar(<?= json_encode($t, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>)'>Editar</button><a class="action-delete" href="index.php?url=dashboard&action=eliminar&id=<?= (int)$t['id'] ?>" onclick="return confirm('¿Deseas eliminar este movimiento?');">Borrar</a></div></td></tr><?php endforeach; else: ?><tr><td colspan="7" class="empty">📜 Todavía no hay movimientos. Registra tu primer ingreso o gasto arriba.</td></tr><?php endif; ?></tbody></table></div></section>
</main></div>
<script>const MAPA_COLORES_FIJOS={'Alimentación':'#247cf3','Vivienda':'#76b7ff','Servicios':'#8e8af0','Transporte':'#63c9ff','Salud':'#52d9c1','Educación':'#2363ad','Entretenimiento':'#5c91ed','Ropa':'#a4c1d3','Mascotas':'#42628d','Suscripciones':'#377fd2','Deudas':'#193d73','Nómina / Salario':'#72cfae','Ventas':'#55b6f2','Freelance':'#42cbb8','Inversiones':'#6eb6ff','Premios / Regalos':'#9ce6d4','Otros':'#9aaac0'};function obtenerColoresFijos(e){return e&&e.length?e.map(c=>MAPA_COLORES_FIJOS[c]||'#9aaac0'):['#cbd5e1']}function cargarParaEditar(t){document.getElementById('formTitulo').innerHTML='Editar Movimiento <span class="scribble">↗</span>';document.getElementById('formAction').value='editar';document.getElementById('formId').value=t.id;document.getElementById('inputTipo').value=t.tipo;document.getElementById('inputMonto').value=t.monto;document.getElementById('inputCategoria').value=t.categoria;document.getElementById('inputMetodo').value=t.metodo_pago;document.getElementById('inputFecha').value=t.fecha;document.getElementById('inputDescripcion').value=t.descripcion||'';document.getElementById('btnSubmit').innerText='Actualizar Movimiento';document.getElementById('btnCancelar').style.display='block';window.scrollTo({top:0,behavior:'smooth'})}function cancelarEdicion(){document.getElementById('formTitulo').innerHTML='Registrar movimiento <span class="scribble">↗</span>';document.getElementById('formAction').value='guardar';document.getElementById('formId').value='';document.getElementById('formTransaccion').reset();document.getElementById('inputFecha').value='<?= date('Y-m-d') ?>';document.getElementById('btnSubmit').innerText='Guardar movimiento ✈';document.getElementById('btnCancelar').style.display='none'}document.addEventListener('DOMContentLoaded',function(){new Chart(document.getElementById('graficoComparativo'),{type:'line',data:{labels:<?= json_encode($fechasComparativa??['Sin registros']) ?>,datasets:[{label:'Ingresos',data:<?= json_encode($datosIngresosLinea??[0]) ?>,borderColor:'#247cf3',backgroundColor:'rgba(36,124,243,.08)',tension:.3,borderWidth:3,pointRadius:4},{label:'Gastos',data:<?= json_encode($datosGastosLinea??[0]) ?>,borderColor:'#ff4f7b',backgroundColor:'rgba(255,79,123,.06)',tension:.3,borderWidth:3,pointRadius:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{beginAtZero:true}}}});const ingE=<?= json_encode($catIngresosEtiquetas??[]) ?>,ingD=<?= json_encode($cantIngresos??[]) ?>,gasE=<?= json_encode($catGastosEtiquetas??[]) ?>,gasD=<?= json_encode($cantGastos??[]) ?>;new Chart(document.getElementById('graficoIngresos'),{type:'doughnut',data:{labels:ingE.length?ingE:['Sin Ingresos'],datasets:[{data:ingD.length?ingD:[1],backgroundColor:ingD.length?obtenerColoresFijos(ingE):['#9ed6ff'],borderWidth:3,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'65%',plugins:{legend:{position:'bottom'}}}});new Chart(document.getElementById('graficoGastos'),{type:'doughnut',data:{labels:gasE.length?gasE:['Sin Gastos'],datasets:[{data:gasD.length?gasD:[1],backgroundColor:gasD.length?obtenerColoresFijos(gasE):['#ff9db7'],borderWidth:3,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'65%',plugins:{legend:{position:'bottom'}}}})});</script></body></html>
